#!/bin/sh
# Prints the Homebrew formula of a release, for orelang/homebrew-tap:
#   ci/formula.sh <tag> <SHA256SUMS>
# It installs the release's self-contained archive for the machine (LLVM and
# lld are inside), so it has no dependencies.
set -eu
tag=$1
sums=$2
version=${tag#v}
base=https://github.com/orelang/ore/releases/download/$tag
sum() { grep "  ore-$tag-$1.tar.gz\$" "$sums" | cut -d' ' -f1; }
cat <<EOF
# Generated by ci/formula.sh of orelang/ore for $tag; do not edit.
class Ore < Formula
  desc "Compiler of the Ore language: TypeScript syntax, Go-like semantics, native code"
  homepage "https://github.com/orelang/ore"
  version "$version"

  on_macos do
    on_arm do
      url "$base/ore-$tag-darwin-arm64.tar.gz"
      sha256 "$(sum darwin-arm64)"
    end
  end

  on_linux do
    on_intel do
      url "$base/ore-$tag-linux-amd64.tar.gz"
      sha256 "$(sum linux-amd64)"
    end
    on_arm do
      url "$base/ore-$tag-linux-arm64.tar.gz"
      sha256 "$(sum linux-arm64)"
    end
  end

  def install
    libexec.install Dir["*"]
    bin.install_symlink libexec/"bin/ore"
  end

  test do
    (testpath/"hello.ore").write "console.log(\\"hello\\")\\n"
    assert_equal "hello\\n", shell_output("#{bin}/ore run #{testpath}/hello.ore")
  end
end
EOF
